using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.PaymentVouchers.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.PaymentVouchers.Commands.AddPaymentVoucherAllocation;public sealed class AddPaymentVoucherAllocationCommandHandler(IPaymentVoucherRepository repository,IPurchaseInvoiceRepository purchases,IApplicationDbContext db):IRequestHandler<AddPaymentVoucherAllocationCommand,Result<PaymentVoucherAllocationDto>>{public async Task<Result<PaymentVoucherAllocationDto>>Handle(AddPaymentVoucherAllocationCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.PaymentVoucherId,cancellationToken);if(e is null)return Result.Failure<PaymentVoucherAllocationDto>(PaymentVoucherErrors.NotFound);if(e.Status!="Draft")return Result.Failure<PaymentVoucherAllocationDto>(PaymentVoucherErrors.NotDraft);if(await purchases.FindByIdAsync(request.PurchaseInvoiceId,cancellationToken)is null)return Result.Failure<PaymentVoucherAllocationDto>(new Error("PaymentVouchers.PurchaseInvoiceNotFound","The purchase invoice was not found.",ErrorType.NotFound));if(e.Allocations.Sum(x=>x.AllocatedAmount)+request.AllocatedAmount>e.Amount)return Result.Failure<PaymentVoucherAllocationDto>(PaymentVoucherErrors.AllocationExceeded);var a=e.AddAllocation(request.PurchaseInvoiceId,request.AllocatedAmount);await db.SaveChangesAsync(cancellationToken);return Result.Success(PaymentVoucherAllocationDto.FromEntity(a));}}
